require_once __DIR__.'/../includes/bootstrap.php';require_role('admin');$rows=$conn->query('SELECT a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.user_id=a.user_id ORDER BY a.created_at DESC LIMIT 500');page_start('Audit log');echo '<h1>Audit log</h1><p>Most recent 500 security and academic activity records.</p><div class="tablewrap"><table><tr><th>Time</th><th>Actor</th><th>Action</th><th>Record</th><th>Details</th></tr>';while($r=$rows->fetch_assoc())echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['username']??'Unavailable').'</td><td>'.e($r['action']).'</td><td>'.e($r['entity_type'].' #'.$r['entity_id']).'</td><td>'.e($r['details']).'</td></tr>';echo '</table></div>';page_end();
